from pathlib import Path
root=Path('.')

def rw(rel, fn):
    p=root/rel; t=p.read_text(); n=fn(t)
    if n==t: print('WARN no change', rel)
    p.write_text(n)

rw('app/build.gradle', lambda t:t.replace("versionCode 320","versionCode 321").replace("versionName '3.2.0-phase1'","versionName '3.2.0-phase2'"))
rw('app/src/main/java/com/offlineperf/logger/Metrics.java', lambda t:t.replace('public long collectorElapsedMs, sampleIntervalMs;','public long collectorElapsedMs, sampleIntervalMs, scheduledLatenessMs;').replace('public int processCount;','public int processCount;\n        public String cpuFreqsKhz = "";'))

def db(t):
    t=t.replace('private static final int VERSION = 100;','private static final int VERSION = 101;')
    t=t.replace('''        db.execSQL("PRAGMA synchronous=NORMAL");\n        db.execSQL("PRAGMA foreign_keys=ON");\n        db.execSQL("PRAGMA wal_autocheckpoint=2000");''','''        db.setForeignKeyConstraintsEnabled(true);\n        runPragma(db, "PRAGMA synchronous=NORMAL");\n        runPragma(db, "PRAGMA wal_autocheckpoint=2000");''')
    t=t.replace('sample_interval_ms INTEGER,process_count INTEGER','sample_interval_ms INTEGER,scheduled_lateness_ms INTEGER,process_count INTEGER')
    t=t.replace('battery_temp_decic INTEGER,thermal_status INTEGER','battery_temp_decic INTEGER,battery_voltage_mv INTEGER,battery_status INTEGER,battery_current_ua INTEGER,battery_current_avg_ua INTEGER,charge_counter_uah INTEGER,thermal_status INTEGER,thermal_headroom REAL,cpu_freqs_khz TEXT')
    marker='        // Safe for installs upgrading from experimental v3 schemas too.'
    ins='''        if (oldVersion < 101) {\n            addColumnIfMissing(db, "samples", "scheduled_lateness_ms", "INTEGER DEFAULT 0");\n            addColumnIfMissing(db, "samples", "battery_voltage_mv", "INTEGER DEFAULT -1");\n            addColumnIfMissing(db, "samples", "battery_status", "INTEGER DEFAULT -1");\n            addColumnIfMissing(db, "samples", "battery_current_ua", "INTEGER DEFAULT 0");\n            addColumnIfMissing(db, "samples", "battery_current_avg_ua", "INTEGER DEFAULT 0");\n            addColumnIfMissing(db, "samples", "charge_counter_uah", "INTEGER DEFAULT 0");\n            addColumnIfMissing(db, "samples", "thermal_headroom", "REAL");\n            addColumnIfMissing(db, "samples", "cpu_freqs_khz", "TEXT");\n        }\n'''
    t=t.replace(marker,ins+marker)
    t=t.replace('int batteryPct, int batteryTempDeciC, int thermalStatus,\n                             boolean screenOn','int batteryPct, int batteryTempDeciC, int batteryVoltageMv, int batteryStatus,\n                             int batteryCurrentUa, int batteryCurrentAvgUa, int chargeCounterUah, int thermalStatus, float thermalHeadroom,\n                             boolean screenOn')
    t=t.replace('int batteryPct, int batteryTempDeciC, int thermalStatus,\n                                          boolean screenOn','int batteryPct, int batteryTempDeciC, int batteryVoltageMv, int batteryStatus,\n                                          int batteryCurrentUa, int batteryCurrentAvgUa, int chargeCounterUah, int thermalStatus, float thermalHeadroom,\n                                          boolean screenOn')
    t=t.replace('sampleValues(sessionId, s, batteryPct, batteryTempDeciC, thermalStatus, screenOn','sampleValues(sessionId, s, batteryPct, batteryTempDeciC, batteryVoltageMv, batteryStatus, batteryCurrentUa, batteryCurrentAvgUa, chargeCounterUah, thermalStatus, thermalHeadroom, screenOn')
    t=t.replace('int batteryPct, int batteryTempDeciC, int thermalStatus,\n                                              boolean screenOn','int batteryPct, int batteryTempDeciC, int batteryVoltageMv, int batteryStatus,\n                                              int batteryCurrentUa, int batteryCurrentAvgUa, int chargeCounterUah, int thermalStatus, float thermalHeadroom,\n                                              boolean screenOn')
    t=t.replace('v.put("collector_ms", s.collectorElapsedMs); v.put("sample_interval_ms", s.sampleIntervalMs); v.put("process_count", s.processCount);','v.put("collector_ms", s.collectorElapsedMs); v.put("sample_interval_ms", s.sampleIntervalMs); v.put("scheduled_lateness_ms", s.scheduledLatenessMs); v.put("process_count", s.processCount);')
    t=t.replace('v.put("battery_pct", batteryPct); v.put("battery_temp_decic", batteryTempDeciC); v.put("thermal_status", thermalStatus); v.put("screen_on", screenOn ? 1 : 0);','v.put("battery_pct", batteryPct); v.put("battery_temp_decic", batteryTempDeciC); v.put("battery_voltage_mv", batteryVoltageMv); v.put("battery_status", batteryStatus); v.put("battery_current_ua", batteryCurrentUa); v.put("battery_current_avg_ua", batteryCurrentAvgUa); v.put("charge_counter_uah", chargeCounterUah); v.put("thermal_status", thermalStatus); if (!Float.isNaN(thermalHeadroom)) v.put("thermal_headroom", thermalHeadroom); v.put("cpu_freqs_khz", s.cpuFreqsKhz); v.put("screen_on", screenOn ? 1 : 0);')
    old='''    public void checkpointWal(boolean truncate) {\n        try { getWritableDatabase().rawQuery("PRAGMA wal_checkpoint(" + (truncate ? "TRUNCATE" : "PASSIVE") + ")", null).close(); } catch (Throwable ignored) {}\n    }'''
    new='''    public void checkpointWal(boolean truncate) {\n        try (Cursor c = getWritableDatabase().rawQuery("PRAGMA wal_checkpoint(" + (truncate ? "TRUNCATE" : "PASSIVE") + ")", null)) { if (c.moveToFirst()) { } } catch (Throwable ignored) {}\n    }\n\n    private static void runPragma(SQLiteDatabase db, String sql) {\n        try (Cursor c = db.rawQuery(sql, null)) { if (c.moveToFirst()) { } }\n    }\n\n    private static void addColumnIfMissing(SQLiteDatabase db, String table, String column, String declaration) {\n        try (Cursor c = db.rawQuery("PRAGMA table_info(" + table + ")", null)) {\n            while (c.moveToNext()) if (column.equals(c.getString(c.getColumnIndexOrThrow("name")))) return;\n        }\n        db.execSQL("ALTER TABLE " + table + " ADD COLUMN " + column + " " + declaration);\n    }'''
    return t.replace(old,new)
rw('app/src/main/java/com/offlineperf/logger/DiagnosticsDb.java',db)

def sampler(t):
    t=t.replace('private int cachedBatteryPct=-1, cachedBatteryTemp=-1;\n    private long lastBatteryRead;','private int cachedBatteryPct=-1, cachedBatteryTemp=-1, cachedBatteryVoltageMv=-1, cachedBatteryStatus=-1;\n    private long lastBatteryRead, lastThermalHeadroomRead, scheduleBaseElapsed=-1;\n    private float cachedThermalHeadroom=Float.NaN;\n    private final BatteryManager batteryManager;')
    t=t.replace('this.context=context.getApplicationContext();this.db=db;this.packages=packages;this.sessionId=sessionId;','this.context=context.getApplicationContext();this.db=db;this.packages=packages;this.sessionId=sessionId;\n        this.batteryManager=(BatteryManager)this.context.getSystemService(Context.BATTERY_SERVICE);')
    t=t.replace('Metrics.Snapshot s=localFallback();\n            s.sampleIntervalMs=prevSampleElapsed<0?0:Math.max(0,s.elapsedMs-prevSampleElapsed); prevSampleElapsed=s.elapsedMs;','Metrics.Snapshot s=localFallback();\n            if(scheduleBaseElapsed<0) scheduleBaseElapsed=s.elapsedMs;\n            long expected=scheduleBaseElapsed+(sampleCount*700L);\n            s.scheduledLatenessMs=Math.max(0,s.elapsedMs-expected);\n            s.sampleIntervalMs=prevSampleElapsed<0?0:Math.max(0,s.elapsedMs-prevSampleElapsed); prevSampleElapsed=s.elapsedMs;\n            s.cpuFreqsKhz=cpuFreqsKhz();')
    t=t.replace('''            int thermal=android.os.Build.VERSION.SDK_INT>=29?pm.getCurrentThermalStatus():-1;\n            long now=s.elapsedMs;\n            if(now-lastBatteryRead>=10_000||lastBatteryRead==0){int[] b=battery();cachedBatteryPct=b[0];cachedBatteryTemp=b[1];lastBatteryRead=now;}''','''            int thermal=android.os.Build.VERSION.SDK_INT>=29?pm.getCurrentThermalStatus():-1;\n            long now=s.elapsedMs;\n            if(android.os.Build.VERSION.SDK_INT>=30 && (lastThermalHeadroomRead==0 || now-lastThermalHeadroomRead>=10_000)){\n                try{cachedThermalHeadroom=pm.getThermalHeadroom(0);}catch(Throwable ignored){cachedThermalHeadroom=Float.NaN;}\n                lastThermalHeadroomRead=now;\n            }\n            float thermalHeadroom=cachedThermalHeadroom;\n            if(now-lastBatteryRead>=1_400||lastBatteryRead==0){int[] b=battery();cachedBatteryPct=b[0];cachedBatteryTemp=b[1];cachedBatteryVoltageMv=b[2];cachedBatteryStatus=b[3];lastBatteryRead=now;}\n            int currentUa=batteryProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_NOW);\n            int currentAvgUa=batteryProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_AVERAGE);\n            int chargeCounterUah=batteryProperty(BatteryManager.BATTERY_PROPERTY_CHARGE_COUNTER);''')
    t=t.replace('long processInterval=screen?5_000:15_000;','long processInterval=screen?2_800:7_000;')
    t=t.replace('sampleId=db.insertSampleWithProcesses(sessionId,s,cachedBatteryPct,cachedBatteryTemp,thermal,screen,rx,tx,selfCpu,selfRssKb(),true,top,screen?"periodic_5s":"periodic_15s_screen_off");','sampleId=db.insertSampleWithProcesses(sessionId,s,cachedBatteryPct,cachedBatteryTemp,cachedBatteryVoltageMv,cachedBatteryStatus,currentUa,currentAvgUa,chargeCounterUah,thermal,thermalHeadroom,screen,rx,tx,selfCpu,selfRssKb(),true,top,screen?"periodic_2.8s":"periodic_7s_screen_off");')
    t=t.replace('sampleId=db.insertSample(sessionId,s,cachedBatteryPct,cachedBatteryTemp,thermal,screen,rx,tx,selfCpu,selfRssKb(),deepReady);','sampleId=db.insertSample(sessionId,s,cachedBatteryPct,cachedBatteryTemp,cachedBatteryVoltageMv,cachedBatteryStatus,currentUa,currentAvgUa,chargeCounterUah,thermal,thermalHeadroom,screen,rx,tx,selfCpu,selfRssKb(),deepReady);')
    t=t.replace('private int[] battery(){Intent i=context.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null)return new int[]{-1,-1};int level=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=i.getIntExtra(BatteryManager.EXTRA_SCALE,100);int pct=level<0?-1:Math.round(level*100f/Math.max(1,scale));return new int[]{pct,i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,-1)};}','private int[] battery(){Intent i=context.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null)return new int[]{-1,-1,-1,-1};int level=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=i.getIntExtra(BatteryManager.EXTRA_SCALE,100);int pct=level<0?-1:Math.round(level*100f/Math.max(1,scale));return new int[]{pct,i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,-1),i.getIntExtra(BatteryManager.EXTRA_VOLTAGE,-1),i.getIntExtra(BatteryManager.EXTRA_STATUS,-1)};}\n    private int batteryProperty(int id){try{long v=batteryManager==null?Long.MIN_VALUE:batteryManager.getLongProperty(id);return v==Long.MIN_VALUE?0:(int)Math.max(Integer.MIN_VALUE,Math.min(Integer.MAX_VALUE,v));}catch(Throwable t){return 0;}}\n    private static String cpuFreqsKhz(){StringBuilder b=new StringBuilder();int miss=0;for(int i=0;i<32&&miss<4;i++){String path="/sys/devices/system/cpu/cpu"+i+"/cpufreq/scaling_cur_freq";try(BufferedReader r=new BufferedReader(new FileReader(path))){String v=r.readLine();if(v!=null){if(b.length()>0)b.append(\';\');b.append(i).append(\'=\').append(v.trim());miss=0;}else miss++;}catch(Throwable x){miss++;}}return b.toString();}')
    return t
rw('app/src/main/java/com/offlineperf/logger/Sampler.java',sampler)
rw('app/src/main/java/com/offlineperf/logger/LoggerService.java', lambda t:t.replace('coreScheduler.scheduleAtFixedRate(()->guard("core",this::runCoreTick),0,1,TimeUnit.SECONDS);','coreScheduler.scheduleAtFixedRate(()->guard("core",this::runCoreTick),0,700,TimeUnit.MILLISECONDS);').replace('String text=started?"1 s system • adaptive processes • "+duration()','String text=started?"700 ms core • adaptive processes • "+duration()'))
def export(t):
    return t.replace('device-diagnostics-forensics-v3.2-phase1','device-diagnostics-forensics-v3.2-phase2').replace('j.put("system_sample_target_ms", 1000);','j.put("system_sample_target_ms", 700);').replace('j.put("process_scan_screen_on_ms", 5000);','j.put("process_scan_screen_on_ms", 2800);').replace('j.put("process_scan_screen_off_ms", 15000);','j.put("process_scan_screen_off_ms", 7000);').replace('j.put("flight_recorder_ms", 250);','j.put("flight_recorder_ms", 250);\n        j.put("battery_current_sampling_ms", 700);\n        j.put("battery_static_sampling_ms", 1400);\n        j.put("cpu_frequency_sampling_ms", 700);\n        j.put("thermal_headroom_sampling_ms", 10000);')
rw('app/src/main/java/com/offlineperf/logger/ExportManager.java',export)
